#include "observer_internal.hpp"
#include "control_internal.hpp"
#include <fstream>
#include <sstream>
#include <iostream>
#include <iomanip>
#include <map>
#include <set>
#include <chrono>
#include <cmath>
#include <limits>
#include <algorithm>
namespace fs=std::filesystem;
static std::vector<std::string> split(std::string s,char sep='\t'){if(!s.empty()&&s.back()=='\r')s.pop_back();std::stringstream ss(s);std::vector<std::string> v;std::string t;while(std::getline(ss,t,sep))v.push_back(t);return v;}
struct Row{std::string date,path,group,session;int fold,index;double y,t;cv::Mat j,c;};
static std::string sess(const Row&r){if(r.date!="20261014")return r.date;if(r.t!=0)return r.t>0?"S3_T+":"S4_T-";bool odd=std::llabs(std::llround(r.y/.05))%2;return r.y>0?(odd?"S5_Y+":"S1_Y+"):(odd?"S6_Y-":"S2_Y-");}
static cv::Mat parse(const std::string&s,int n){auto v=split(s,';');if(int(v.size())!=n)throw std::runtime_error("feature size");cv::Mat x(1,n,CV_64F);for(int k=0;k<n;++k)x.at<double>(k)=std::stod(v[k]);return x;}
static cv::Mat precision(const cv::Mat&R,double shrink,int df){cv::Mat S=R.t()*R/double(std::max(1,R.rows-df)),D=cv::Mat::eye(R.cols,R.cols,CV_64F);for(int k=0;k<R.cols;++k)D.at<double>(k,k)=1/std::sqrt(std::max(S.at<double>(k,k),1e-14));cv::Mat corr=(1-shrink)*(D*S*D)+shrink*cv::Mat::eye(R.cols,R.cols,CV_64F),inv;cv::invert(corr,inv,cv::DECOMP_SVD);return D*inv*D;}
struct Joint{cv::Mat B,W,P;std::vector<cv::Mat> origins;std::vector<std::string> names;};
static Joint fitJ(const std::vector<Row*>&tr,bool multi){Joint m;std::set<std::string> names;for(auto*r:tr)names.insert(multi?r->session:"common");m.names.assign(names.begin(),names.end());int K=int(m.names.size());cv::Mat A=cv::Mat::zeros(int(tr.size()),2+K,CV_64F),X(int(tr.size()),204,CV_64F);for(int i=0;i<X.rows;++i){auto*r=tr[i];A.at<double>(i,0)=r->y;A.at<double>(i,1)=r->t;auto it=std::find(m.names.begin(),m.names.end(),multi?r->session:"common");A.at<double>(i,2+int(it-m.names.begin()))=1;r->j.copyTo(X.row(i));}cv::Mat co;cv::solve(A,X,co,cv::DECOMP_SVD);m.B=co.rowRange(0,2).clone();cv::Mat R=X-A*co;
// Match earlier GLS baseline: residual divisor N, sd floor 1e-6.
cv::Mat sd(1,204,CV_64F),Z=R.clone();for(int k=0;k<204;++k){sd.at<double>(k)=std::max(std::sqrt(R.col(k).dot(R.col(k))/R.rows),1e-6);Z.col(k)/=sd.at<double>(k);}cv::Mat cov=.99*(Z.t()*Z/double(Z.rows))+.01*cv::Mat::eye(204,204,CV_64F),ci;cv::invert(cov,ci,cv::DECOMP_SVD);cv::Mat D=cv::Mat::eye(204,204,CV_64F);for(int k=0;k<204;++k)D.at<double>(k,k)=1/sd.at<double>(k);m.W=D*ci*D;
cv::Mat bs=m.B.clone();for(int k=0;k<204;++k)bs.col(k)/=sd.at<double>(k);cv::Mat Q;cv::solve(cov,bs.t(),Q,cv::DECOMP_SVD);cv::Mat gram=bs*Q,inv;cv::invert(gram,inv,cv::DECOMP_SVD);m.P=Q*inv;for(int k=0;k<204;++k)m.P.row(k)/=sd.at<double>(k);for(int k=0;k<K;++k)m.origins.push_back(co.row(2+k).clone());return m;}
struct Prediction{double y=std::numeric_limits<double>::quiet_NaN(),t=std::numeric_limits<double>::quiet_NaN(),cost=1e300;std::string branch="none";};
static Prediction predict(const Joint&m,const cv::Mat&x){Prediction a;for(size_t k=0;k<m.origins.size();++k){cv::Mat z=x-m.origins[k],q=z*m.P,r=z-q*m.B;double cost=r.dot(r*m.W);if(cost<a.cost){a={q.at<double>(0),q.at<double>(1),cost,m.names[k]};}}return a;}
struct Control{cv::Mat s,c,W;std::vector<cv::Mat> origins;std::vector<std::string> names;bool gate;};
static Control fitC(const std::vector<Row*>&tr,int mode){Control m;m.gate=mode==0;std::set<std::string> names;for(auto*r:tr)names.insert(mode==0?r->session:"common");m.names.assign(names.begin(),names.end());int K=mode==2?0:int(m.names.size());cv::Mat A=cv::Mat::zeros(int(tr.size()),2+K,CV_64F),X(int(tr.size()),12,CV_64F);for(int i=0;i<X.rows;++i){auto*r=tr[i];A.at<double>(i,0)=r->y;A.at<double>(i,1)=r->y*r->y;if(K){auto it=std::find(m.names.begin(),m.names.end(),mode==0?r->session:"common");A.at<double>(i,2+int(it-m.names.begin()))=1;}r->c.copyTo(X.row(i));}cv::Mat co;cv::solve(A,X,co,cv::DECOMP_SVD);m.s=co.row(0).clone();m.c=co.row(1).clone();m.W=precision(X-A*co,.05,2+K);if(!K){m.origins.push_back(cv::Mat::zeros(1,12,CV_64F));m.names={"center_fixed"};}else for(int k=0;k<K;++k)m.origins.push_back(co.row(2+k).clone());return m;}
static Prediction predict(const Control&m,const cv::Mat&x){Prediction a;cv::Mat sw=m.s*m.W;for(size_t k=0;k<m.origins.size();++k){cv::Mat z=x-m.origins[k];double v=z.dot(sw)/m.s.dot(sw);for(int j=0;j<8;++j){cv::Mat jac=m.s+2*v*m.c,r=z-v*m.s-v*v*m.c;v+=jac.dot(r*m.W)/std::max(jac.dot(jac*m.W),1e-20);}if(m.gate&&v*(m.names[k].back()=='+'?1:-1)<0)continue;cv::Mat r=z-v*m.s-v*v*m.c;double cost=r.dot(r*m.W);if(cost<a.cost)a={v,0,cost,m.names[k]};}return a;}
static cv::Mat fmap(const cv::Mat&x){cv::Mat z(1,204,CV_64F);x.copyTo(z.colRange(0,102));double h=0;for(int k=0;k<54;k+=2)h+=x.at<double>(k);h/=2700.;for(int k=0;k<102;++k)z.at<double>(k+102)=x.at<double>(k)*h;return z;}
int main(int argc,char**argv){try{if(argc!=4)throw std::runtime_error("origin_eval REPO PRIOR_DIR OUT");auto root=fs::u8path(argv[1]),prior=fs::u8path(argv[2]),out=fs::u8path(argv[3]);if(fs::exists(out))throw std::runtime_error("Output exists");fs::create_directories(out);cv::setNumThreads(1);std::ifstream in(prior/"input.tsv");std::string line;std::getline(in,line);std::vector<Row> rows;while(std::getline(in,line)){auto v=split(line);Row r;r.date=v.at(0);r.path=v.at(1);r.y=std::stod(v.at(2));r.t=std::stod(v.at(3));r.fold=std::stoi(v.at(4));r.group=v.at(5);r.index=int(rows.size());r.session=sess(r);rows.push_back(r);}std::ifstream feat(prior/"results/features.tsv");std::getline(feat,line);int count=0;while(std::getline(feat,line)){auto v=split(line);int i=std::stoi(v.at(0));rows.at(i).j=parse(v.at(1),204);rows.at(i).c=parse(v.at(2),12);++count;}if(count!=571||rows.size()!=571)throw std::runtime_error("Expected 571 rows");std::map<std::string,int> gf;for(auto&r:rows){if(gf.count(r.group)&&gf[r.group]!=r.fold)throw std::runtime_error("Group leak");gf[r.group]=r.fold;}
alignment_detail::Observer obs(root/std::filesystem::u8path(u8"experiments/hye/20261104_1435_v2_joint_강등/assets"));legacy_control::Tracker tracker(root/std::filesystem::u8path(u8"experiments/hye/20261104_1435_v2_control_강등/assets"));std::vector<Row> centers;std::vector<fs::path> paths={root/std::filesystem::u8path(u8"experiments/hye/20261104_1435_v2_joint_강등/assets/center.bmp")};auto clean=fs::u8path(rows[280].path);while(clean.filename()!="clean_20261020"&&clean.has_parent_path()&&clean!=clean.parent_path())clean=clean.parent_path();if(clean.filename()!="clean_20261020") {for(auto&r:rows)if(r.date=="20261020"){clean=fs::u8path(r.path);while(clean.filename()!="clean_20261020")clean=clean.parent_path();break;}}for(int k=1;k<=3;++k)paths.push_back(clean/fs::u8path(u8"기준 위치")/("center"+std::to_string(k)+".bmp"));for(int k=0;k<4;++k){auto im=alignment_detail::read_gray(paths[k]);Row r;r.index=571+k;r.date=k?"20261020":"20261014";r.y=r.t=0;r.fold=0;r.path=paths[k].u8string();r.group=r.session=k?"center1020_"+std::to_string(k):"center1014";r.j=fmap(obs.measure(im).values);r.c=tracker.features(tracker.measure(im));centers.push_back(r);}
std::ofstream pr(out/"predictions.tsv"),zeros(out/"origins.tsv");pr<<std::setprecision(17)<<"protocol\tmodel\tsplit\tindex\tdate\tsession\tgroup\tY\tT\tpred_Y\tpred_T\tbranch\tcost\tpredict_ms\n";zeros<<std::setprecision(17)<<"protocol\tsplit\torigin\tkind\tqr_dx\tqr_dy\n";
auto emit=[&](const std::string&p,const std::string&m,const std::string&sp,const Row&r,const Prediction&q,double time){pr<<p<<'\t'<<m<<'\t'<<sp<<'\t'<<r.index<<'\t'<<r.date<<'\t'<<r.session<<'\t'<<r.group<<'\t'<<r.y<<'\t'<<r.t<<'\t'<<q.y<<'\t'<<q.t<<'\t'<<q.branch<<'\t'<<q.cost<<'\t'<<time<<'\n';};
auto run=[&](const std::string&protocol,const std::string&sp,const std::vector<Row*>&tr,const std::vector<Row*>&te){std::vector<Row*>ct;for(auto*r:tr)if(r->t==0)ct.push_back(r);auto one=fitJ(tr,false),many=fitJ(tr,true),ten=many;ten.origins.clear();ten.names.clear();for(size_t k=0;k<many.names.size();++k)if(many.names[k][0]=='S'){ten.names.push_back(many.names[k]);ten.origins.push_back(many.origins[k]);}for(auto&r:centers){ten.names.push_back(r.session);ten.origins.push_back(r.j);}std::vector<std::pair<std::string,Joint>> jm={{"joint_single",one},{"joint_multi_session",many},{"joint_multi_6trial_4center",ten}};
std::vector<std::pair<std::string,Control>> cm;if(ct.size()>=12)for(int k=0;k<3;++k)cm.push_back({k==0?"control_multi_T0":k==1?"control_single_learned":"control_single_center_fixed",fitC(ct,k)});
for(size_t k=0;k<ten.origins.size();++k){double dx=0,dy=0;for(int j=0;j<54;j+=2){dx+=ten.origins[k].at<double>(j)/27;dy+=ten.origins[k].at<double>(j+1)/27;}zeros<<protocol<<'\t'<<sp<<'\t'<<ten.names[k]<<'\t'<<(ten.names[k][0]=='S'?"training_extrapolation":"measured_center")<<'\t'<<dx<<'\t'<<dy<<'\n';}
for(auto*r:te){for(auto&m:jm){auto st=std::chrono::steady_clock::now();auto q=predict(m.second,r->j);double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-st).count();emit(protocol,m.first,sp,*r,q,ms);}for(auto&m:cm){auto st=std::chrono::steady_clock::now();auto q=predict(m.second,r->c);double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-st).count();emit(protocol,m.first,sp,*r,q,ms);}}
if(protocol=="group5"){cv::FileStorage save((out/("models_"+sp+".yml")).u8string(),cv::FileStorage::WRITE);save<<"train_n"<<int(tr.size())<<"control_T0_train_n"<<int(ct.size());for(auto&m:jm){save<<m.first<<"{"<<"B"<<m.second.B<<"W"<<m.second.W<<"P"<<m.second.P<<"origins"<<"[";for(auto&o:m.second.origins)save<<o;save<<"]"<<"names"<<"[";for(auto&n:m.second.names)save<<n;save<<"]"<<"}";}for(auto&m:cm){save<<m.first<<"{"<<"s"<<m.second.s<<"c"<<m.second.c<<"W"<<m.second.W<<"origins"<<"[";for(auto&o:m.second.origins)save<<o;save<<"]"<<"}";}}
std::cout<<protocol<<" "<<sp<<" train="<<tr.size()<<" control="<<ct.size()<<" test="<<te.size()<<std::endl;};
for(int f=1;f<=5;++f){std::vector<Row*>tr,te;for(auto&r:rows)(r.fold==f?te:tr).push_back(&r);run("group5",std::to_string(f),tr,te);}for(auto name:{"S1_Y+","S2_Y-","S3_T+","S4_T-","S5_Y+","S6_Y-"}){std::vector<Row*>tr,te;for(auto&r:rows)(r.session==name?te:tr).push_back(&r);run("leave_session",name,tr,te);}for(auto date:{"20261014","20261020","20261029"}){std::vector<Row*>tr,te;for(auto&r:rows)(r.date==date?te:tr).push_back(&r);run("leave_date",date,tr,te);}std::vector<Row*>all,z;for(auto&r:rows)all.push_back(&r);for(auto&r:centers)z.push_back(&r);run("center_replay","all_training",all,z);return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
